def command(args, **kwargs):
    return subprocess.check_output(args, text=True, **kwargs).strip()


def inspect_sources():
    sources = {}
    for root, expected in PLAN["sources"].items():
        value = {
            "head": command(["git", "-C", root, "rev-parse", "HEAD"]),
            "tree": command(["git", "-C", root, "rev-parse", "HEAD^{tree}"]),
            "status": command(["git", "-C", root, "status", "--porcelain"]),
        }
        if value != expected | {"status": ""}:
            raise RuntimeError(f"source mismatch: {root}: {value}")
        sources[root] = value
    for path, expected in PLAN["sha256"].items():
        if digest(path) != expected:
            raise RuntimeError(f"fingerprint changed: {path}")
    receipt = json.loads(Path(PLAN["historical_reference"]).read_text())["checkpoint"]
    checkpoint = Path(PLAN["checkpoint"])
    assets = {}
    for entry in receipt["assets"]:
        actual = digest(checkpoint / entry["name"])
        if actual != entry["master_sha256"]:
            raise RuntimeError(f"checkpoint asset changed: {entry['name']}")
        assets[entry["name"]] = actual
    shards = []
    for entry in receipt["shards"]:
        stat = (checkpoint / entry["relative_path"]).stat()
        actual = {"device": stat.st_dev, "inode": stat.st_ino, "bytes": stat.st_size, "mtime_ns": stat.st_mtime_ns}
        expected = {"device": entry["master_device"], "inode": entry["master_inode"], "bytes": entry["bytes"], "mtime_ns": entry["mtime_ns"]}
        if actual != expected:
            raise RuntimeError(f"checkpoint shard identity changed: {entry['relative_path']}")
        shards.append({"path": entry["relative_path"], **actual})
    return {"utc": datetime.now(timezone.utc).isoformat(), "sources": sources,
            "assets_sha256": assets, "shard_stat_identity": shards,
            "payload_hashes_recomputed": False,
            "native_extensions_sha256": {str(p): digest(p) for p in Path(PLAN["cwd"]).joinpath("vllm").rglob("*.so")},
            "bundle_sha256": {p.name: digest(p) for p in BUNDLE.iterdir() if p.suffix in (".py", ".sh", ".md") or p.name == "plan.json"}}


def check(directory):
    write(directory / "sources-before.json", inspect_sources())
    env = PLAN["environment"] | {"CUDA_VISIBLE_DEVICES": ""}
    with (directory / "cli-validation.log").open("w") as log:
        subprocess.run([str(BUNDLE / "with-source-isolation.sh"), PLAN["python"],
                        str(BUNDLE / "validate_cli.py"), str(directory / "cli-validation.json")],
                       cwd=PLAN["cwd"], env=env, stdout=log, stderr=subprocess.STDOUT,
                       check=True, timeout=90)
    with (directory / "cache-sizing.log").open("w") as log:
        subprocess.run([str(BUNDLE / "with-source-isolation.sh"), PLAN["python"],
                        str(BUNDLE / "cache_geometry.py"), str(directory / "cache-sizing.json")],
                       cwd=PLAN["cwd"], env=env, stdout=log, stderr=subprocess.STDOUT,
                       check=True, timeout=90)
    write(directory / "sources-after-check.json", inspect_sources())
    return json.loads((directory / "cli-validation.json").read_text())


def launch(directory):
    check(directory)
    with socket.socket() as probe:
        probe.bind(("127.0.0.1", PLAN["port"]))
    gpu = command(["nvidia-smi", f"--id={PLAN['gpu_uuid']}",
                   "--query-gpu=uuid,name,memory.total,memory.used,driver_version", "--format=csv,noheader"])
    processes = command(["nvidia-smi", f"--id={PLAN['gpu_uuid']}",
                         "--query-compute-apps=pid,process_name,used_memory", "--format=csv,noheader"])
    write(directory / "gpu-before.json", {"gpu": gpu, "compute_processes": processes})
    if processes:
        raise RuntimeError("assigned GPU has an existing compute process; no process was stopped")
    write(directory / "launch.json", PLAN)
    stopped = False

    def stop(signum, frame):
        nonlocal stopped
        stopped = True

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    started = time.monotonic()
    status = {"label": PLAN["label"], "ready": False, "status": "starting"}
    child = None
    try:
        with (directory / "server.log").open("w") as log:
            child = subprocess.Popen(PLAN["command"], cwd=PLAN["cwd"], env=PLAN["environment"],
                                     stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
            write(directory / "controller.json", {"controller_pid": os.getpid(), "server_pid": child.pid,
                                                    "server_process_group": child.pid})
            url = f"http://127.0.0.1:{PLAN['port']}"
            opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
            while child.poll() is None and not stopped:
                if time.monotonic() - started > PLAN["readiness_timeout_seconds"]:
                    raise TimeoutError("readiness deadline exceeded; inspect server.log")
                try:
                    with opener.open(url + "/health", timeout=2) as response:
                        assert response.status == 200
                    with opener.open(url + "/v1/models", timeout=2) as response:
                        models = json.load(response)
                    if [row["id"] for row in models["data"]] != [PLAN["model_id"]]:
                        raise RuntimeError(f"unexpected served model: {models}")
                    proc = Path(f"/proc/{child.pid}")
                    argv = [x.decode() for x in (proc / "cmdline").read_bytes().split(b"\0") if x]
                    expected_argv = PLAN["command"][1:]
                    environment = dict(x.decode().split("=", 1) for x in (proc / "environ").read_bytes().split(b"\0") if x)
                    if argv != expected_argv or any(environment.get(k) != v for k, v in PLAN["environment"].items()):
                        raise RuntimeError("running argv/environment differs from the planned launch")
                    write(directory / "actual-launch.json", {"pid": child.pid, "argv": argv,
                          "environment": {key: environment[key] for key in PLAN["environment"]},
                          "argv_matches_plan": True, "environment_matches_plan": True})
                    status.update(ready=True, status="ready", startup_seconds=time.monotonic() - started)
                    write(directory / "ready.json", status | {"models": models})
                    print(f"READY {url} {directory}", flush=True)
                    break
                except (urllib.error.URLError, ConnectionError, TimeoutError):
                    time.sleep(1)
            if not status["ready"] and not stopped:
                raise RuntimeError(f"server exited before readiness: {child.poll()}")
            while child.poll() is None and not stopped:
                time.sleep(0.5)
            status["status"] = "stopped" if stopped else "exited"
    except BaseException as error:
        status.update(status="failed", error=repr(error))
        raise
    finally:
        if child is not None:
            try:
                os.killpg(child.pid, signal.SIGTERM)
            except ProcessLookupError:
                pass
            deadline = time.monotonic() + PLAN["shutdown_grace_seconds"]
            while time.monotonic() < deadline:
                child.poll()
                try:
                    os.killpg(child.pid, 0)
                except ProcessLookupError:
                    break
                time.sleep(0.5)
            else:
                status["forced_kill"] = True
                try:
                    os.killpg(child.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
            status["server_exit_code"] = child.wait(timeout=15)
        status["elapsed_seconds"] = time.monotonic() - started
        write(directory / "status.json", status)
        if (directory / "server.log").exists():
            write(directory / "log-sha256.json", {"server.log": digest(directory / "server.log")})
        try:
            write(directory / "sources-after.json", inspect_sources())
        except Exception as error:
            write(directory / "sources-after-error.json", {"error": repr(error)})
        try:
            after = command(["nvidia-smi", f"--id={PLAN['gpu_uuid']}",
                             "--query-compute-apps=pid,process_name,used_memory", "--format=csv,noheader"])
            write(directory / "gpu-after.json", {"compute_processes": after})
        except Exception as error:
            write(directory / "gpu-after-error.json", {"error": repr(error)})


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--launch", action="store_true")
    parser.add_argument("--run-dir", required=True, type=Path)
    args = parser.parse_args()
    args.run_dir.mkdir(parents=True, exist_ok=False)
    if args.launch:
        launch(args.run_dir)
    else:
        check(args.run_dir)
        print(f"CPU checks passed: {args.run_dir}")
